  var TYPE_META = {
    d:{name:"Доминирование", color:"var(--d-color)"},
    i:{name:"Влияние",       color:"var(--i-color)"},
    s:{name:"Стабильность",  color:"var(--s-color)"},
    c:{name:"Соответствие",  color:"var(--c-color)"}
  };
  var TYPE_DESC = {
    d:"Вы решаете и действуете уверенно, берёте инициативу и ведёте за собой. Сильная сторона — решительность и энергия; следите за тем, чтобы слышать других.",
    i:"Вы оптимистичны и открыты, заряжаете людей и настраиваете команду на positives. Сильная сторона — коммуникация и вдохновение; держите фокус на деталях.",
    s:"Вы спокойны, надёжны и внимательны к людям. Сильная сторона — стабильность и поддержка; иногда смелее выставляйте свою точку зрения.",
    c:"Вы точны, ответственно и системно. Сильная сторона — анализ и порядок; не бойтесь быстрее принимать решения."
  };

  /* ---------- Состояние ---------- */
  var currentStep = 0;
  var TOTAL = STEPS.length;
  var listBackup = {};
  var rootWizard;
  var tabButtons = [];
  var panes = [];
  var resultsEl;
  var scrollLock = false;

  function qs(sel){ return document.querySelector(sel); }
  function qsa(sel){ return Array.prototype.slice.call(document.querySelectorAll(sel)); }

  /* ---------- Скролл-лок ---------- */
  function lockScroll(on){
    if(on){
      if(!scrollLock) document.body.style.height = window.innerHeight + "px";
      document.body.classList.add("disc-no-scroll");
    } else {
      document.body.classList.remove("disc-no-scroll");
      document.body.style.height = "";
    }
  }

  /* ---------- Построение шагов ---------- */
  function buildPanes(){
    rootWizard = qs("#rootwizard");
    STEPS.forEach(function(step, idx){
      var pane = document.createElement("div");
      pane.className = "disc-pane" + (idx===0 ? " is-active" : "");
      pane.setAttribute("data-step-pane", idx);
      pane.setAttribute("role","tabpanel");
      var grid = document.createElement("div");
      grid.className = "disc-grid3";
      step.forEach(function(cols){
        var card = document.createElement("div");
        card.className = "disc-card";
        var title = document.createElement("div");
        title.className = "disc-card__title";
        title.textContent = "Я наиболее";
        var list = document.createElement("ul");
        list.className = "disc-list";
        cols.forEach(function(col){
          var li = document.createElement("li");
          li.className = "disc-item";
          li.setAttribute("data-type", col[0]);
          li.textContent = col[1];
          list.appendChild(li);
        });
        var foot = document.createElement("div");
        foot.className = "disc-card__foot";
        foot.textContent = "Я наименее";
        card.appendChild(title); card.appendChild(list); card.appendChild(foot);
        grid.appendChild(card);
      });
      pane.appendChild(grid);
      rootWizard.appendChild(pane);
      panes.push(pane);
    });
    tabButtons = qsa(".disc-modal__tabs .disc-tab");
    resultsEl = qs("#discResults");
    // бэкап исходного порядка списков
    qsa(".disc-list").forEach(function(ul){ listBackup[ul.id || "list_"+Math.random()] = ul.innerHTML; });
    // присвоим id спискам по порядку, чтобы бэкап работал стабильно
    var lists = qsa(".disc-list");
    lists.forEach(function(ul, i){ ul.id = "dl" + i; });
    // пере-запоминаем бэкап с id
    listBackup = {};
    lists.forEach(function(ul){ listBackup[ul.id] = ul.innerHTML; });
    makeListSortable();
  }

  /* ---------- Сортировка (перетаскивание) ---------- */
  var drag = null; // {item, list, ghost, offsetX, offsetY, newIndex}
  function makeListSortable(){
    qsa(".disc-list").forEach(function(listEl){
      listEl.addEventListener("pointerdown", function(e){
        if(drag) return;
        var item = e.target.closest ? e.target.closest(".disc-item") : null;
        if(!item) return;
        startDrag(item, listEl, e);
      });
    });
  }
  function startDrag(item, listEl, e){
    if(e.preventDefault) e.preventDefault();
    var rect = item.getBoundingClientRect();
    var ghost = item.cloneNode(true);
    ghost.id = "";
    ghost.className = "disc-item disc-ghost";
    ghost.style.pointerEvents = "none";
    document.body.appendChild(ghost);
    drag = {
      item:item, list:listEl, ghost:ghost,
      offsetX:e.clientX-rect.left, offsetY:e.clientY-rect.top,
      newIndex:0
    };
    item.classList.add("is-dragging");
    positionGhost(ghost, e.clientX, e.clientY);
    document.addEventListener("pointermove", onDragMove, {passive:false});
    document.addEventListener("pointerup", onDragUp, {passive:false});
    document.addEventListener("pointercancel", onDragUp, {passive:false});
    document.addEventListener("blur", onDragUp, {passive:false});
  }
  function positionGhost(g, x, y){
    g.style.left = (x - drag.offsetX) + "px";
    g.style.top  = (y - drag.offsetY) + "px";
  }
  function onDragMove(e){
    if(!drag) return;
    e.preventDefault();
    positionGhost(drag.ghost, e.clientX, e.clientY);
    var siblings = Array.prototype.filter.call(drag.list.children, function(n){
      return n !== drag.item && n.tagName === "LI";
    });
    var ni = siblings.length;
    for(var i=0;i<siblings.length;i++){
      var r = siblings[i].getBoundingClientRect();
      if(e.clientY < r.top + r.height/2){ ni = i; break; }
    }
    if(ni !== drag.newIndex){
      drag.newIndex = ni;
      drag.list.removeChild(drag.item);
      var s2 = Array.prototype.filter.call(drag.list.children, function(n){ return n.tagName === "LI"; });
      if(ni < s2.length) drag.list.insertBefore(drag.item, s2[ni]);
      else drag.list.appendChild(drag.item);
    }
  }
  function onDragUp(){
    if(!drag) return;
    var it = drag.item, gh = drag.ghost, ls = drag.list;
    if(gh.parentNode) gh.parentNode.removeChild(gh);
    it.classList.remove("is-dragging");
    // фиксируем порядок: убираем is-dragging (item уже на своём месте)
    // очищаем
    document.removeEventListener("pointermove", onDragMove);
    document.removeEventListener("pointerup", onDragUp);
    document.removeEventListener("pointercancel", onDragUp);
    document.removeEventListener("blur", onDragUp);
    drag = null;
    // пересчитываем прогресс
    updateProgress();
  }

  /* ---------- Навигация шагов ---------- */
  function setStep(step){
    currentStep = step;
    panes.forEach(function(p){
      var a = parseInt(p.getAttribute("data-step-pane"),10) === step;
      p.classList.toggle("is-active", a);
    });
    tabButtons.forEach(function(t){
      var a = parseInt(t.getAttribute("data-step-btn"),10) === step;
      t.classList.toggle("is-active", a);
      t.setAttribute("aria-selected", a ? "true":"false");
    });
    rootWizard.setAttribute("data-step", currentStep);
    var prev = qs("[data-disc-prev]"), next = qs("[data-disc-next]"), fin = qs("[data-disc-finish]");
    if(prev) prev.disabled = (currentStep === 0);
    if(next) next.disabled = (currentStep === TOTAL-1);
    if(fin) fin.hidden = (currentStep !== TOTAL-1);
    updateProgress();
  }
  function updateProgress(){
    var bar = qs("#discProgress");
    if(bar) bar.style.width = (currentStep/(TOTAL-1)*100) + "%";
  }

  /* ---------- Сбор результатов ---------- */
  function countArr(arr, t){ var n=0; for(var i=0;i<arr.length;i++) if(arr[i]===t) n++; return n; }
  function collectScore(){
    var maj=[], min=[];
    qsa(".disc-list").forEach(function(list){
      var items = list.querySelectorAll(".disc-item");
      var n = items.length;
      if(n<2) return;
      var first = items[0], last = items[n-1];
      maj.push(first.getAttribute("data-type"));
      min.push(last.getAttribute("data-type"));
    });
    return {
      d: countArr(maj,"d")-countArr(min,"d"),
      i: countArr(maj,"i")-countArr(min,"i"),
      s: countArr(maj,"s")-countArr(min,"s"),
      c: countArr(maj,"c")-countArr(min,"c")
    };
  }

  /* ---------- Результаты ---------- */
  function showResults(score){
    // скрываем тест, показываем результаты
    var tabsEl = qs(".disc-modal__tabs");
    if(tabsEl) tabsEl.hidden = true;
    if(rootWizard) rootWizard.hidden = true;
    resultsEl.hidden = false;
    // максимальный диапазон
    var maxAbs = 24;
    var order = ["d","i","s","c"];
    var vals = {};
    order.forEach(function(t){ vals[t] = score[t]; });
    var top = Math.max.apply(Math, order.map(function(t){ return vals[t]; }));
    var tops = order.filter(function(t){ return vals[t] === top; }).slice();
    var topName = tops.map(function(t){ return TYPE_META[t].name; }).join(", ");
    var topLetter = tops.map(function(t){ return t.toUpperCase(); }).join(" / ");

    var html = [
      "<div class='disc-results__title'>Ваши результаты</div>",
      "<div class='disc-results__sub'>Профиль поведения по модели DISC</div>",
      "<div class='disc-results__dom'><b>" + esc(topLetter) + "</b> главный тип: " + esc(topName) + "</div>",
      "<div class='disc-results__types'>"
    ].join("");

    order.forEach(function(t){
      var pct = Math.max(0, Math.min(100, (vals[t] + maxAbs) / (2 * maxAbs) * 100));
      html += "<div class='disc-type-card'>"
        + "<div class='disc-type-card__top'>"
        +   "<span class='disc-type-card__name'>" + t.toUpperCase() + " · " + TYPE_META[t].name + "</span>"
        +   "<span class='disc-type-card__score' style='color:" + TYPE_META[t].color + "'>" + fmtScore(vals[t]) + "</span>"
        + "</div>"
        + "<div class='disc-type-card__bar'><span class='disc-type-card__fill' style='width:" + pct.toFixed(1) + "%; --bar:" + TYPE_META[t].color + "'></span></div>"
        + "</div>";
    });
    html += "</div>";

    // описание: краткое описание каждого типа
    html += "<div class='disc-results__desc'>";
    html += "<b>О ваших типах:</b><br>";
    order.forEach(function(t){
      html += "<span style='color:" + TYPE_META[t].color + ";font-weight:700'>" + t.toUpperCase() + "</span> — " + TYPE_META[t].name + ". ";
    });
    html += "</div>";
    html += "<div class='disc-actions disc-actions__reset'>"
      + "<button class='disc-btn disc-btn--primary' id='resetDisc' type='button'>Пройти заново</button>"
      + "</div>";

    resultsEl.innerHTML = html;
    // оживляем бары
    requestAnimationFrame(function(){ requestAnimationFrame(function(){ animateFills(); }); });
    qs("#resetDisc").addEventListener("click", function(){ resetTest(); });
  }
  function fmtScore(v){
    if(v === 0) return "0";
    return v > 0 ? "+" + v : String(v);
  }
  function esc(s){
    return String(s).replace(/[&<>"']/g, function(c){
      return c === "&" ? "&amp;" : c === "<" ? "&lt;" : c === ">" ? "&gt;" : c === '"' ? "&quot;" : "&#39;";
    });
  }
  function animateFills(){
    qsa(".disc-type-card__fill").forEach(function(f){
      var w = f.getAttribute("style"); // уже в style; просто для анимации
    });
    // просто гарантируем, что fill уже имеет ширину (CSS transition от 0)
  }

  /* ---------- Сброс ---------- */
  function resetTest(){
    // восстанавливаем исходный порядок списков
    qsa(".disc-list").forEach(function(ul){
      ul.innerHTML = listBackup[ul.id] || ul.innerHTML;
    });
    setStep(0);
    resultsEl.hidden = true;
    var tabsEl = qs(".disc-modal__tabs"); if(tabsEl) tabsEl.hidden = false;
    if(rootWizard) rootWizard.hidden = false;
  }

  /* ---------- Открытие/закрытие модалки ---------- */
  function openModal(el){
    if(!el || el.tagName !== "DIV" || el.id === "apruve") return;
    lockScroll(true);
    el.setAttribute("aria-hidden","false");
    el.classList.add("is-open");
  }
  function closeModal(elId){
    var el = elId ? document.getElementById(elId) : null;
    if(!el) return;
    if(drag){
      var it = drag.item, gh = drag.ghost;
      if(gh && gh.parentNode) gh.parentNode.removeChild(gh);
      if(it) it.classList.remove("is-dragging");
      document.removeEventListener("pointermove", onDragMove);
      document.removeEventListener("pointerup", onDragUp);
      document.removeEventListener("pointercancel", onDragUp);
      document.removeEventListener("blur", onDragUp);
      drag = null;
    }
    el.setAttribute("aria-hidden","true");
    el.classList.remove("is-open");
    lockScroll(false);
  }

  /* ---------- Инициализация ---------- */
  function init(){
    buildPanes();
    setStep(0);

    // открытие через [data-modal-open]
    qsa("[data-modal-open]").forEach(function(btn){
      btn.addEventListener("click", function(){
        openModal(document.getElementById(btn.getAttribute("data-modal-open")));
      });
    });
    // закрытие через [data-disc-close]
    qsa("[data-disc-close]").forEach(function(el){
      el.addEventListener("click", function(){ closeModal("wizardmodal"); });
    });
    // Esc
    document.addEventListener("keydown", function(e){
      if(e.key === "Escape"){
        var open = document.querySelector(".disc-modal.is-open");
        if(open) closeModal(open.id);
      }
    });
    // действия
    qs("[data-disc-prev]").addEventListener("click", function(){
      if(currentStep > 0) setStep(currentStep - 1);
    });
    qs("[data-disc-next]").addEventListener("click", function(){
      if(currentStep < TOTAL - 1) setStep(currentStep + 1);
    });
    qs("[data-disc-finish]").addEventListener("click", function(){
      var score = collectScore();
      showResults(score);
    });
  }

  if(document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
</script>
</body>
</html>
</html>
